#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const root = process.cwd();
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const payload = '';
const bundle = JSON.parse(zlib.gunzipSync(Buffer.from(payload, 'base64')).toString('utf8'));

function backupIfExists(relativePath) {
  const target = path.join(root, relativePath);
  if (!fs.existsSync(target)) return;
  const backup = path.join(root, relativePath + `.before-authored-book3-${stamp}`);
  fs.copyFileSync(target, backup);
  console.log(`Backed up ${relativePath} -> ${path.relative(root, backup)}`);
}

backupIfExists('src/slides.js');
backupIfExists('scripts/build-slides.mjs');
backupIfExists('lectures/manifest.json');

for (const [relativePath, content] of Object.entries(bundle.files)) {
  const target = path.join(root, relativePath);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content.endsWith('\n') ? content : content + '\n');
}

const manifestPath = path.join(root, 'lectures/manifest.json');
let manifest = [];
if (fs.existsSync(manifestPath)) {
  try { manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8')); }
  catch { manifest = []; }
}
manifest = manifest.filter(entry => entry && entry.courseId !== bundle.courseId);
manifest.push(...bundle.entries);
manifest.sort((a, b) => String(a.courseId).localeCompare(String(b.courseId)) || Number(a.chapter) - Number(b.chapter));
fs.mkdirSync(path.dirname(manifestPath), { recursive: true });
fs.writeFileSync(manifestPath, JSON.stringify(manifest) + '\n');

const slideCount = bundle.entries.reduce((total, entry) => total + JSON.parse(bundle.files[entry.path]).slides.length, 0);
console.log(`Installed authored Book III Slides: ${bundle.entries.length} decks, ${slideCount} slides.`);
console.log('Next: run node scripts/build-slides.mjs, then npm start.');
